select t.slug, t.name, sl.level::text as lvl, t.sort_order, (select string_agg(ss.code||' '||ss.title, ' ; ' order by ss.sort_order) from syllabus_statements ss where ss.topic_id=t.id) as stmts, (select count(*) from questions q join quizzes z on z.id=q.quiz_id where z.topic_id=t.id) as qs, (select count(*) from flashcards f join flashcard_sets fs on fs.id=f.set_id where fs.topic_id=t.id) as fc from topics t join subject_levels sl on sl.id=t.subject_level_id join subjects s on s.id=sl.subject_id where s.name ilike '%physics%' and sl.level::text ilike '%as%' order by t.sort_order nulls last, t.slug;
